const cveId = $('On form submission').first().json['CVE ID'].trim().toUpperCase();
const raw = String($input.first().json.output ?? '');

// Local models sometimes wrap the JSON in code fences or add a sentence around it,
// so we take everything between the first "{" and the last "}"
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end <= start) {
  throw new Error(`Agent did not return a JSON object for ${cveId}: ${raw.slice(0, 200)}`);
}

let r;
try {
  r = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error(`Agent returned invalid JSON for ${cveId}: ${e.message}`);
}

if (!['P1', 'P2', 'P3', 'P4'].includes(r.priority)) {
  throw new Error(`Invalid priority "${r.priority}" for ${cveId}`);
}

// Small type slips are repaired instead of failing the whole run
const toList = v => (Array.isArray(v) ? v.map(String) : v ? [String(v)] : []);
const toNumberOrNull = v =>
  v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v);
const s = r.signals ?? {};

return [{
  json: {
    cveId,                                   // from the form, never from the model
    priority: r.priority,
    reason: String(r.reason ?? ''),
    whatItIs: String(r.whatItIs ?? ''),
    affected: toList(r.affected).slice(0, 5),
    fixedVersions: toList(r.fixedVersions),
    advisoryUrl: r.advisoryUrl ? String(r.advisoryUrl) : null,
    signals: {
      cvssScore: toNumberOrNull(s.cvssScore),
      epss: toNumberOrNull(s.epss),
      inKev: s.inKev === true,
      hasExploitReference: s.hasExploitReference === true,
    },
    dataGaps: toList(r.dataGaps),
    triagedAt: new Date().toISOString(),
  },
}];
